let LA_failed = 0
ItemEvents.modification(event => {
  for (const id of Object.keys(LA_FIX)) {
    try {
      event.modify(id, item => {
        const entries = []
        LA_FIX[id].forEach(e => {
          const modId = LA_RL.parse('leakaudit:' + id.replace(':', '_') + '_' + e[0].toLowerCase())
          entries.push(new LA_ENTRY(LA_ATTRS[e[0]], new LA_AM(modId, e[1], LA_OP[e[3]]), LA_SLOTS[e[2]]))
        })
        item.setAttributeModifiersWithTooltip(entries)
      })
    } catch (err) {
      if (LA_failed++ < 3) console.info("leak-audit power fix FAILED for " + id + ": " + err)
    }
  }
})
